 function sync(){const k=[state.mu,state.sigma,state.n].join(':');if(k===key)return;key=k;clear();newQuiz();if(state.step===4&&u.mode==='demo'){begin();u.goal=1;u.running=true;}actions();lastDom='';}
 function reset(){clear();u.phase=0;u.standardRunning=false;key='';sync();actions();update();}
 function enter(step,autoplay=false){pause();u.view=step;if(step===4){if(autoplay)u.mode='demo';if(u.mode==='demo'){if(!u.batch||u.studentPhase==='recorded')begin();u.goal=Infinity;u.fast=false;u.running=true;}}if(step===6){u.phase=0;u.standardRunning=autoplay;}actions();update();}
 function setMode(mode){manual();u.mode=mode;u.batch=null;u.progress=0;u.studentPhase='ready';u.guess=null;u.feedback='';$('sampling-answer').value='';benchStamp='';actions();update();}
 $('sampling-mode-student').onclick=()=>setMode('student');$('sampling-mode-demo').onclick=()=>setMode('demo');
 function setGuess(value){if(u.mode!=='student'||u.studentPhase!=='drawn'||!Number.isFinite(value))return;u.guess=value;u.feedback='';$('sampling-answer').value=fmt(value,2);updateWorkbench();invalidate();}
