  if(hasHistogram){for(let i=0;i<hist.counts.length;i++){if(!hist.counts[i])continue;const x=lo+i*hist.width,y=hist.densities[i];fill([q(x,0),q(x,y),q(x+hist.width*.92,y),q(x+hist.width*.92,0)],C.green,.25);line([q(x,0),q(x,y),q(x+hist.width*.92,y),q(x+hist.width*.92,0)],'#86a580',.7);}}
